    UNION ALL SELECT 'GT_DMF0082_TEMP_SITE_ITEM_V2' T, 'DIVISION_ID|VARCHAR2|10|||Y;PROJECT_CODE|VARCHAR2|50|||Y;SCM_SITE_ID|VARCHAR2|50|||Y;ITEM_ID|VARCHAR2|50|||Y;CELL_MODEL|VARCHAR2|200|||Y;NICK_NAME|VARCHAR2|200|||Y;DMS_SALES|VARCHAR2|200|||Y;DMS_CUSTOMER|VARCHAR2|200|||Y;OWNER|VARCHAR2|200|||Y;DEPT_ID|VARCHAR2|50|||Y;DEPT_NAME_KO|VARCHAR2|200|||Y;FORECAST_INFO_CELL_PACK_COUNT|NUMBER|0|20|10|Y;ITEM_TYPE|VARCHAR2|50|||Y;PROJECT_NAME|VARCHAR2|200|||Y;PROJECT_OWNER|VARCHAR2|200|||Y;BIZ_TYPE|VARCHAR2|50|||Y;SOLDTO_CUSTOMER|VARCHAR2|200|||Y;COUNTRY_NAME|VARCHAR2|200|||Y;CITY_NAME|VARCHAR2|200|||Y;PROJECT_STATUS|VARCHAR2|50|||Y;ITEM_NAME|VARCHAR2|200|||Y;VMI_YN|VARCHAR2|1|||Y;CUST_GROUP|VARCHAR2|200|||Y;CUST_GROUP_DTL|VARCHAR2|200|||Y;APPLICATION|VARCHAR2|200|||Y;ROUTE|VARCHAR2|200|||Y;MDM_PROJECT_NAME|VARCHAR2|200|||Y;MIN_CAPACITY|VARCHAR2|100|||Y;FORECAST_INFO_BIZ_TYPE|VARCHAR2|200|||Y;CELL_TYPE|VARCHAR2|50|||Y;FORECAST_INFO_ALL|VARCHAR2|200|||Y;FORECAST_INFO_SPEC|VARCHAR2|200|||Y;FORECAST_INFOR_VERSION|VARCHAR2|200|||Y;CELL_MODEL_NICK_NAME|VARCHAR2|200|||Y;CELL_PER_CAR|NUMBER|0|20|10|Y;CELL_PER_MODULE|NUMBER|0|20|10|Y;MODULE_PER_CAR|NUMBER|0|20|10|Y;SORT_ORDER_NO|NUMBER|0|20|10|Y;ENERGE|VARCHAR2|50|||Y;CELL_QUANTITY|NUMBER|0|20|10|Y;PLANT_SITE_ID|VARCHAR2|50|||Y;ITEM_VALID_YN|VARCHAR2|1|||Y;END_CUSTOMER|VARCHAR2|200|||Y;PROJECT_S_OP_REPORT|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_LAST_DATA_SETUP_FCST' T, 'DIVISION_ID|VARCHAR2|10|||Y;PROJECT_CODE|VARCHAR2|50|||Y;SCM_SITE_ID|VARCHAR2|50|||Y;ITEM_ID|VARCHAR2|50|||Y;DOM_EXP|VARCHAR2|10|||Y;FCST_TYPE|VARCHAR2|50|||Y;INCOTERMS|VARCHAR2|50|||Y;MEASURE|VARCHAR2|100|||Y;CREATE_DATE|DATE|0|||Y;LAST_UPDATED_BY|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_LAST_DATA_SETUP_FCST_C' T, 'DIVISION_ID|VARCHAR2|10|||Y;PROJECT_CODE|VARCHAR2|50|||Y;SCM_SITE_ID|VARCHAR2|50|||Y;ITEM_ID|VARCHAR2|50|||Y;DOM_EXP|VARCHAR2|10|||Y;FCST_TYPE|VARCHAR2|50|||Y;INCOTERMS|VARCHAR2|50|||Y;MEASURE|VARCHAR2|100|||Y;VERSION_NO|VARCHAR2|100|||Y;CREATE_DATE|DATE|0|||Y;LAST_UPDATED_BY|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_LAST_DATA_SETUP_PRICE' T, 'DIVISION_ID|VARCHAR2|10|||Y;PROJECT_CODE|VARCHAR2|50|||Y;SCM_SITE_ID|VARCHAR2|50|||Y;ITEM_ID|VARCHAR2|50|||Y;DOM_EXP|VARCHAR2|10|||Y;FCST_TYPE|VARCHAR2|50|||Y;INCOTERMS|VARCHAR2|50|||Y;MEASURE|VARCHAR2|100|||Y;CREATE_DATE|DATE|0|||Y;LAST_UPDATED_BY|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_LAST_DATA_SETUP_PRICE_C' T, 'DIVISION_ID|VARCHAR2|10|||Y;PROJECT_CODE|VARCHAR2|50|||Y;SCM_SITE_ID|VARCHAR2|50|||Y;ITEM_ID|VARCHAR2|50|||Y;DOM_EXP|VARCHAR2|10|||Y;FCST_TYPE|VARCHAR2|50|||Y;INCOTERMS|VARCHAR2|50|||Y;MEASURE|VARCHAR2|100|||Y;CREATE_DATE|DATE|0|||Y;LAST_UPDATED_BY|VARCHAR2|200|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_VERSION' T, 'VERSION_NO|VARCHAR2|100|||Y;VERSION_NO_W|VARCHAR2|100|||Y;NOW_YYYYMMDD|VARCHAR2|8|||Y;SP_VERSION_NO|VARCHAR2|100|||Y' S FROM DUAL
    UNION ALL SELECT 'GT_DMF0082_T_WS_FCST' T, 'FCST_TYPE|VARCHAR2|50|||Y' S FROM DUAL) E
 WHERE NVL((SELECT LISTAGG(COLUMN_NAME||'|'||DATA_TYPE||'|'||CHAR_LENGTH||'|'||DATA_PRECISION||'|'||DATA_SCALE||'|'||NULLABLE, ';') WITHIN GROUP (ORDER BY COLUMN_ID)
              FROM USER_TAB_COLUMNS C WHERE C.TABLE_NAME = E.T), '~') <> E.S
 ORDER BY 1;

/* 4) META — 패키지 행이 클라우드에 모두 있음: MISSING = 0 */
SELECT 'SCM_ADM_MNU_M' AS TBL, '메뉴 행 (메뉴 트리·노출은 클라우드 운영값 존중 — 없을 때만)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_M T WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'DMF0082' MNU_ID FROM DUAL) S;
SELECT 'SCM_ADM_API_M' AS TBL, '화면 전용 API' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_API_M T WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'DMF0082_FcstNPrice_HEADER' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_GET_CURRENT' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_GET_EXCEL_FORM' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_GET_UPLOAD_DATA' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_buttonAuth_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_futurePriceInfo_IF' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_futurePriceInfo_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_futurePriceInfo_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_futurePriceInfo_SEARCH_DATA' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_futurePriceInfo_TITLE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_main_UPLOAD' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_savePriceData_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_savePriceTitle_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_spreadTitle_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_titleSet_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_titleSet_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_upload_SAVE' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_version_SEARCH' API_ID FROM DUAL) S;
SELECT 'SCM_ADM_API_M' AS TBL, '공용 API(이 화면 버튼이 씀)' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_API_M T WHERE NVL(TO_CHAR(T.API_ID), '~') = NVL(TO_CHAR(S.API_ID), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'P_DMF0082_GET_MAIN_DATA' API_ID FROM DUAL) S;
SELECT 'SCM_ADM_MNU_BTN_MPG_M' AS TBL, '버튼 → API 매핑' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_MNU_BTN_MPG_M T WHERE NVL(TO_CHAR(T.MNU_ID), '~') = NVL(TO_CHAR(S.MNU_ID), '~') AND NVL(TO_CHAR(T.SHT_NM), '~') = NVL(TO_CHAR(S.SHT_NM), '~') AND NVL(TO_CHAR(T.MNU_BTN_CD), '~') = NVL(TO_CHAR(S.MNU_BTN_CD), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'DMF0082' MNU_ID, 'FcstNPrice' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'FcstNPrice' SHT_NM, 'FORM_DATA' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'FcstNPrice' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'FcstNPrice' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'FcstNPrice' SHT_NM, 'SEARCH_CURRENT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'FcstNPrice' SHT_NM, 'UPLOAD' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'FcstNPrice' SHT_NM, 'UPLOAD_DATA' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'FcstNPrice' SHT_NM, 'UPLOAD_SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'buttonAuth' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'fcstNPrice' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'fcstNPrice' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'fcstNPrice' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'futurePriceInfo' SHT_NM, 'DELETE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'futurePriceInfo' SHT_NM, 'EDIT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'futurePriceInfo' SHT_NM, 'IF' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'futurePriceInfo' SHT_NM, 'INSERT' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'futurePriceInfo' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'futurePriceInfo' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'futurePriceInfo' SHT_NM, 'SEARCH_DATA' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'futurePriceInfo' SHT_NM, 'TITLE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'savePriceData' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'savePriceTitle' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'spreadTitle' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'titleSet' SHT_NM, 'SAVE' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'titleSet' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL
    UNION ALL SELECT 'DMF0082' MNU_ID, 'version' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL) S;
SELECT 'SCM_ADM_PROC_M' AS TBL, '화면 PKG 프로시저 파라미터' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_ADM_PROC_M T WHERE NVL(TO_CHAR(T.PROC_NM), '~') = NVL(TO_CHAR(S.PROC_NM), '~') AND NVL(TO_CHAR(T.COL_NM), '~') = NVL(TO_CHAR(S.COL_NM), '~') AND NVL(TO_CHAR(T.COL_TP_CD), '~') = NVL(TO_CHAR(S.COL_TP_CD), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'PKG_DMF0082.P_DMF0082_EXCEL_UPLOAD' PROC_NM, 'createdBy' COL_NM, 'IN' COL_TP_CD FROM DUAL
