    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_EXCEL_UPLOAD' PROC_NM, 'programId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_EXCEL_UPLOAD' PROC_NM, 'sheetName' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_BUTTON_AUTH' PROC_NM, 'buttonAuth' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_BUTTON_AUTH' PROC_NM, 'divisionId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_BUTTON_AUTH' PROC_NM, 'measureAuth' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_BUTTON_AUTH' PROC_NM, 'o_result_cursor' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_BUTTON_AUTH' PROC_NM, 'sesUserId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_BUTTON_AUTH' PROC_NM, 'userGroup' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'bizType' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'deptId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'divisionId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'endCustomer' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'fromYyyymmdd' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'itemId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'o_rc1' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'o_result_cursor' COL_NM, 'OUT' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'owner' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'plantSiteId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'projectCode' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'qtyYn' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'salesSite' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'senderCode' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'sesUserId' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'toYyyymmdd' COL_NM, 'IN' COL_TP_CD FROM DUAL
    UNION ALL SELECT 'PKG_DMF0082.P_DMF0082_GET_EXCEL_FORM_DATA' PROC_NM, 'userGroup' COL_NM, 'IN' COL_TP_CD FROM DUAL
