SELECT 'SCM_MST_SHEET_COLUMNS' AS TBL, '시트 컬럼' AS AREA, COUNT(*) AS PKG_ROWS, SUM(CASE WHEN EXISTS (SELECT 1 FROM SCM_MGR.SCM_MST_SHEET_COLUMNS T WHERE NVL(TO_CHAR(T.PROGRAM_ID), '~') = NVL(TO_CHAR(S.PROGRAM_ID), '~') AND NVL(TO_CHAR(T.SHEET_NAME), '~') = NVL(TO_CHAR(S.SHEET_NAME), '~') AND NVL(TO_CHAR(T.COLUMN_NAME), '~') = NVL(TO_CHAR(S.COLUMN_NAME), '~')) THEN 0 ELSE 1 END) AS MISSING
  FROM (SELECT 'DMF0082' PROGRAM_ID, 'FcstNPrice' SHEET_NAME, 'APPLICATION' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'DMF0082' PROGRAM_ID, 'FcstNPrice' SHEET_NAME, 'AS_FROM_SITE' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'DMF0082' PROGRAM_ID, 'FcstNPrice' SHEET_NAME, 'AS_YN' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'DMF0082' PROGRAM_ID, 'FcstNPrice' SHEET_NAME, 'ATTR1' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'DMF0082' PROGRAM_ID, 'FcstNPrice' SHEET_NAME, 'BIZ_TYPE' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'DMF0082' PROGRAM_ID, 'FcstNPrice' SHEET_NAME, 'BUCKET' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'DMF0082' PROGRAM_ID, 'FcstNPrice' SHEET_NAME, 'CELL_MODEL_NICK_NAME' COLUMN_NAME FROM DUAL
    UNION ALL SELECT 'DMF0082' PROGRAM_ID, 'FcstNPrice' SHEET_NAME, 'CELL_PER_CAR' COLUMN_NAME FROM DUAL
