   AND NOT EXISTS (SELECT 1 FROM (SELECT 'DMF0082_FcstNPrice_HEADER' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_GET_CURRENT' API_ID FROM DUAL
