    UNION ALL SELECT 'DMF0082_futurePriceInfo_SEARCH' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_futurePriceInfo_SEARCH_DATA' API_ID FROM DUAL
    UNION ALL SELECT 'DMF0082_futurePriceInfo_TITLE' API_ID FROM DUAL
